// final class Node { var val: Int; var next, random: Node?; init(_ v: Int) { val = v } }
func copyRandomList(_ head: Node?) -> Node? {
    var map: [ObjectIdentifier: Node] = [:]
    var cur = head
    while let n = cur { map[ObjectIdentifier(n)] = Node(n.val); cur = n.next }
    cur = head
    while let n = cur {
        let copy = map[ObjectIdentifier(n)]!
        copy.next = n.next.map { map[ObjectIdentifier($0)]! }
        copy.random = n.random.map { map[ObjectIdentifier($0)]! }
        cur = n.next
    }
    return head.map { map[ObjectIdentifier($0)]! }
}
